CREATE DEFINER=`u208271556_agenteai`@`127.0.0.1` PROCEDURE `create_view_files_ant` (IN `patient_id` BIGINT)   BEGIN
	CREATE OR REPLACE VIEW files_of_patient_in_ant AS
	WITH RECURSIVE numbers AS (
	  SELECT 1 AS n
	  UNION ALL
	  SELECT n + 1 FROM numbers WHERE n < 100
	)
	SELECT 
		T.*,
		SUBSTRING_INDEX(SUBSTRING_INDEX(T.archivos, ",", n), ",", -1) AS archivo
	FROM antecedents AS T, numbers
	WHERE 
	  n <= (LENGTH(T.archivos) - LENGTH(REPLACE(T.archivos, ",", "")) + 1)
	  AND SUBSTRING_INDEX(SUBSTRING_INDEX(T.archivos, ",", n), ",", -1) != "";
	SELECT * FROM files_of_patient_in_ant AS F WHERE F.patient_id = patient_id;
END$$

CREATE DEFINER=`u208271556_agenteai`@`127.0.0.1` PROCEDURE `create_view_files_card` (IN `p_cita_id` BIGINT)   BEGIN
    WITH RECURSIVE numbers AS (
        SELECT 1 AS n
        UNION ALL
        SELECT n + 1
        FROM numbers
        WHERE n < 100
    )
    SELECT
        T.*,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(T.archivos, ',', n), ',', -1)) AS archivo
    FROM analisis_cardiologicos T
    JOIN numbers
        ON n <= 1 + LENGTH(T.archivos) - LENGTH(REPLACE(T.archivos, ',', ''))
    WHERE T.cita_id = p_cita_id
      AND T.archivos IS NOT NULL
      AND T.archivos <> '';
END$$

CREATE DEFINER=`u208271556_agenteai`@`127.0.0.1` PROCEDURE `create_view_files_gabi` (IN `p_cita_id` BIGINT)   BEGIN
    WITH RECURSIVE numbers AS (
        SELECT 1 AS n
        UNION ALL
        SELECT n + 1
        FROM numbers
        WHERE n < 100
    )
    SELECT
        T.*,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(T.archivos, ',', n), ',', -1)) AS archivo
    FROM analisis_gabinetes T
    JOIN numbers
        ON n <= 1 + LENGTH(T.archivos) - LENGTH(REPLACE(T.archivos, ',', ''))
    WHERE T.cita_id = p_cita_id
      AND T.archivos IS NOT NULL
      AND T.archivos <> '';
END$$

CREATE DEFINER=`u208271556_agenteai`@`127.0.0.1` PROCEDURE `create_view_files_lab` (IN `p_cita_id` BIGINT)   BEGIN
    WITH RECURSIVE numbers AS (
        SELECT 1 AS n
        UNION ALL
        SELECT n + 1
        FROM numbers
        WHERE n < 100
    )
    SELECT
        T.*,
        TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(T.archivos, ',', n), ',', -1)) AS archivo
    FROM laboratorios T
    JOIN numbers
        ON n <= 1 + LENGTH(T.archivos) - LENGTH(REPLACE(T.archivos, ',', ''))
    WHERE T.cita_id = p_cita_id
      AND T.archivos IS NOT NULL
      AND T.archivos <> '';
END$$

